"""Typed campaign records and revision-aware reconciliation."""
from common import Invalid, address, decode64, decimal, ident, MAX_TIME

DELETE = ('delete',)

# Canonical semantic content of a live put.
(T_TYPE, T_LEASE, T_EVENT, T_PROBE, T_TARGET, T_RESPONDER, T_RESULT,
 T_SERVICE, T_ATTEMPT, T_PAYLOAD) = range(10)


def parse_record(values, leases, services, probes):
    """Validate one logical CSV record and return its canonical row."""
    if len(values) != 14:
        raise Invalid('field count')
    typ = values[0]
    if typ != 'icmp' and typ != 'app':
        raise Invalid('record type')
    rid = values[1]
    if not ident(rid):
        raise Invalid('record id')
    revision = decimal(values[2], 10 ** 9)
    published = decimal(values[3], MAX_TIME)
    op = values[4]
    if op == 'delete':
        for value in values[5:]:
            if value != '':
                raise Invalid('delete payload')
        return (typ, rid, published, revision, DELETE)
    if op != 'put':
        raise Invalid('record op')
    lease = values[5]
    info = leases.get(lease)
    if info is None:
        raise Invalid('unknown lease')
    event = decimal(values[6], MAX_TIME)
    if event < info['start'] or event >= info['end'] or event > published:
        raise Invalid('event window')
    target = address(values[8])
    result = values[10]
    if typ == 'icmp':
        probe = values[7]
        entry = probes[lease].get(probe)
        if entry is None or entry[0] != target:
            raise Invalid('probe mismatch')
        if result != 'echo' and result != 'error' and result != 'timeout':
            raise Invalid('icmp result')
        if values[11] != '' or values[12] != '' or values[13] != '':
            raise Invalid('icmp extra fields')
        if result == 'timeout':
            if values[9] != '':
                raise Invalid('timeout responder')
            responder = None
        else:
            responder = address(values[9])
        return (typ, rid, published, revision,
                (typ, lease, event, probe, target, responder, result, '', 0, b''))
    if values[7] != '' or values[9] != '':
        raise Invalid('app probe or responder')
    service = values[11]
    kind = services.get(service)
    if kind is None:
        raise Invalid('unknown service')
    if result != 'open' and result != 'closed' and result != 'timeout':
        raise Invalid('app result')
    attempt = decimal(values[12], 10 ** 6)
    payload = decode64(values[13], Invalid)
    if len(payload) > 65536:
        raise Invalid('payload size')
    if (result != 'open' or kind == 'tcp') and payload:
        raise Invalid('payload not empty')
    return (typ, rid, published, revision,
            (typ, lease, event, '', target, None, result, service, attempt, payload))


class Reconciler:
    """Group rows by (type,id) and replay them over increasing query times."""

    def __init__(self, records):
        groups = {}
        for row in records:
            key = (row[0], row[1])
            bucket = groups.get(key)
            if bucket is None:
                groups[key] = [row]
            else:
                bucket.append(row)
        for bucket in groups.values():
            bucket.sort(key=_published)
        self.groups = groups
        self.state = {key: [0, -1, {}] for key in groups}

    def advance(self, at):
        """Fold every row published no later than `at` and report live rows."""
        live = []
        deleted = 0
        conflict = 0
        for key, rows in self.groups.items():
            state = self.state[key]
            ptr = state[0]
            best = state[1]
            contents = state[2]
            total = len(rows)
            while ptr < total and rows[ptr][2] <= at:
                row = rows[ptr]
                ptr += 1
                revision = row[3]
                if revision > best:
                    best = revision
                    contents = {row[4]: 1}
                elif revision == best:
                    content = row[4]
                    if content in contents:
                        contents[content] += 1
                    else:
                        contents[content] = 1
            state[0] = ptr
            state[1] = best
            state[2] = contents
            if contents:
                if len(contents) == 1:
                    content = next(iter(contents))
                    if len(content) == 1:
                        deleted += 1
                    else:
                        live.append(content)
                else:
                    conflict += 1
        return {'live': len(live), 'deleted': deleted, 'conflict': conflict}, live


def _published(row):
    return row[2]
PYEOF
